//! 🎟️ Actual owned stack preparation follows one finite stock through child and output custody.
use super::*;
use semio_framework_value::{RetainedCloneGrant,work::RetainedWorkLedger};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[path="../../../../../◻️2d/🛤️path/🎟️work/🧪️tests/🦀️.rs"] mod stack_wallet;
fn law()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn stock(v:&serde_json::Value)->RetainedCloneGrant{let v=&v["stock"];let n=|key|v[key].as_u64().unwrap()as usize;RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copy"),maximum_capacity_bytes:n("capacity"),maximum_release_bytes:n("release"),maximum_depth:n("depth")}}
fn input(v:&serde_json::Value)->RasterStackInput{RasterStackInput{layers:vec![RasterStackLayer{id:v["layer"]["id"].as_str().unwrap().into(),visible:true,opacity:1.,blend_mode:CompositeBlend::Normal,transform:RasterStackTransform{x:0.,y:0.,a:1.,b:0.,c:0.,d:1.},mask:None,content:RasterStackContent::Pixel{width:Some(v["layer"]["width"].as_u64().unwrap()as u32),height:Some(v["layer"]["height"].as_u64().unwrap()as u32),image_key:Some(v["image"]["key"].as_str().unwrap().into())}}],images:vec![(v["image"]["key"].as_str().unwrap().into(),RasterLease(Arc::new(RasterImage{width:v["image"]["width"].as_u64().unwrap()as u32,height:v["image"]["height"].as_u64().unwrap()as u32,pixels:serde_json::from_value(v["image"]["rgba"].clone()).unwrap()})))]}}
#[test]
fn owned_stack_and_every_reached_child_use_actual_same_stock_and_independent_tiny_skia_output(){
 let v=law();let input=input(&v);let layers=input.layers.as_ptr();let images=input.images.as_ptr();let(mut job,h)=observe(||RasterStackJob::new(input));assert!(!h.overflowed);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(job.input.layers.as_ptr(),layers);assert_eq!(job.input.images.as_ptr(),images);let mut wallet=stack_wallet::Wallet::from_grant(stock(&v),v["maximumTurns"].as_u64().unwrap()as usize);let mut done=false;
 for _ in 0..v["maximumTurns"].as_u64().unwrap(){let d=job.next_work_demand();for axis in v["axes"].as_array().unwrap(){let axis=axis.as_str().unwrap();if match axis{"items"=>false,"copy"=>d.copy_bytes==0,"capacity"=>d.capacity_bytes==0,"release"=>d.release_bytes==0,"depth"=>d.depth==0,_=>unreachable!()}{continue}let mut grant=wallet.remaining();grant.maximum_items=1;match axis{"items"=>grant.maximum_items=0,"copy"=>grant.maximum_copy_bytes=d.copy_bytes-1,"capacity"=>grant.maximum_capacity_bytes=d.capacity_bytes-1,"release"=>grant.maximum_release_bytes=d.release_bytes-1,"depth"=>grant.maximum_depth=d.depth-1,_=>unreachable!()}let mut work=RetainedWorkLedger::new(grant);let before=job.progress();let(result,h)=observe(||job.advance(1,&mut work));assert_eq!(result.unwrap(),before);assert_eq!(job.last_turn_work(),0);assert_eq!(job.last_turn_semantic_work(),0);assert_eq!(work.receipt(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}
 let p=wallet.turn(1,|work|job.advance(1,work)).unwrap();if p.done{done=true;break}assert!(job.last_turn_work()>0,"finite stack stock cannot progress");}assert!(done);let output=job.result().unwrap();assert_eq!([output.image.width,output.image.height],[v["expected"]["width"].as_u64().unwrap()as u32,v["expected"]["height"].as_u64().unwrap()as u32]);assert_eq!(output.origin,serde_json::from_value::<[f64;2]>(v["expected"]["origin"].clone()).unwrap());assert_eq!(output.empty,v["expected"]["empty"].as_bool().unwrap());assert_eq!(output.image.pixels,serde_json::from_value::<Vec<u8>>(v["expected"]["rgba"].clone()).unwrap());let mut reference=tiny_skia::Pixmap::new(output.image.width,output.image.height).unwrap();let mut path=tiny_skia::PathBuilder::new();path.push_rect(tiny_skia::Rect::from_xywh(0.,0.,output.image.width as f32,output.image.height as f32).unwrap());let mut paint=tiny_skia::Paint::default();paint.set_color_rgba8(255,0,0,255);reference.fill_path(&path.finish().unwrap(),&paint,tiny_skia::FillRule::Winding,tiny_skia::Transform::identity(),None);assert_eq!(output.image.pixels,reference.data());let pointer=output.image.pixels.as_ptr();let((owner,output),h)=observe(||job.into_retirement());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));let output=output.unwrap();assert_eq!(output.image.pixels.as_ptr(),pointer);wallet.close_owned(owner);wallet.close_owned(output);
}
#[test]
fn invalid_owned_stack_retains_source_and_cached_error_is_neutral_until_paid_close(){
 let v=law();let mut input=input(&v);if let RasterStackContent::Pixel{image_key,..}=&mut input.layers[0].content{*image_key=Some(v["invalidImageKey"].as_str().unwrap().into())}let pointer=input.layers.as_ptr();let(mut job,h)=observe(||RasterStackJob::new(input));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!(job.input.layers.as_ptr(),pointer);let mut wallet=stack_wallet::Wallet::from_grant(stock(&v),v["maximumTurns"].as_u64().unwrap()as usize);let mut failed=false;
 for _ in 0..v["maximumTurns"].as_u64().unwrap(){if wallet.turn(1,|work|job.advance(1,work)).is_err(){failed=true;break}}assert!(failed);assert!(job.result().is_err());let mut zero=RetainedWorkLedger::new(Default::default());let(result,h)=observe(||job.advance(1,&mut zero));assert!(result.is_err());assert_eq!(job.last_turn_work(),0);assert_eq!(job.last_turn_semantic_work(),0);assert_eq!(zero.receipt(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));let((owner,output),h)=observe(||job.into_retirement());assert!(output.is_none());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));wallet.close_owned(owner);
}
